func weightSum(cs []gen.TemplateCriterion) int {
	n := 0
	for _, c := range cs {
		n += int(c.Weight)
	}
	return n
}

type CriterionInput struct {
	Code, Label, Description, Weight string
	LabelEn, DescriptionEn           string
	Critical                         bool
}

type ChecklistFormData struct {
	Stage    string
	Name     string
	Activate bool
	// Family is the checklist being edited (a new version); 0 = a new checklist.
	Family    int64
	ScopeText string // edit: who the checklist applies to (fixed)
	// New checklist scope: none = general.
	AssetGroupID string
	SystemIDs    []string
	Systems      []Option
	AssetGroups  []Option
	Rows         []CriterionInput
	Errors       []string
}

func (d ChecklistFormData) systemChecked(id string) bool { return slices.Contains(d.SystemIDs, id) }

